// Patches the android/ folder generated by `flutter create`:
// storage permissions, FileProvider, app name, fixed signing key and MainActivity.
// Safe to run multiple times:  dart run tool/patch_platforms.dart
import 'dart:io';

void patch(String path, String Function(String) change) {
  final f = File(path);
  if (!f.existsSync()) return;
  final before = f.readAsStringSync();
  final after = change(before);
  if (after != before) {
    f.writeAsStringSync(after);
    stdout.writeln('patched $path');
  }
}

void main() {
  patch('android/app/src/main/AndroidManifest.xml', (s) {
    const perms = [
      '<uses-permission android:name="android.permission.MANAGE_EXTERNAL_STORAGE"/>',
      '<uses-permission android:name="android.permission.READ_EXTERNAL_STORAGE" android:maxSdkVersion="32"/>',
      '<uses-permission android:name="android.permission.WRITE_EXTERNAL_STORAGE" android:maxSdkVersion="29"/>',
      '<uses-permission android:name="android.permission.REQUEST_INSTALL_PACKAGES"/>',
      '<uses-permission android:name="android.permission.INTERNET"/>',
      '<uses-permission android:name="android.permission.ACCESS_NETWORK_STATE"/>',
    ];
    final block = perms.where((p) => !s.contains(p.split('"')[1])).map((p) => '    $p\n').join();
    if (block.isNotEmpty) {
      final m = RegExp(r'<manifest[^>]*>\s*\n').firstMatch(s);
      if (m != null) s = s.replaceRange(m.end, m.end, block);
    }
    if (!s.contains('requestLegacyExternalStorage')) {
      s = s.replaceFirst('<application', '<application\n        android:requestLegacyExternalStorage="true"');
    }
    if (!s.contains('androidx.core.content.FileProvider')) {
      s = s.replaceFirst('</application>', '''    <provider
            android:name="androidx.core.content.FileProvider"
            android:authorities="\${applicationId}.files"
            android:exported="false"
            android:grantUriPermissions="true">
            <meta-data
                android:name="android.support.FILE_PROVIDER_PATHS"
                android:resource="@xml/file_paths"/>
        </provider>
    </application>''');
    }
    // OneDrive sign-in comes back to ncommander://auth
    if (!s.contains('android:scheme="ncommander"')) {
      s = s.replaceFirst('</activity>', '''    <intent-filter>
                <action android:name="android.intent.action.VIEW"/>
                <category android:name="android.intent.category.DEFAULT"/>
                <category android:name="android.intent.category.BROWSABLE"/>
                <data android:scheme="ncommander" android:host="auth"/>
            </intent-filter>
        </activity>''');
    }
    return s.replaceFirst(RegExp(r'android:label="[^"]*"'), 'android:label="Ncommander"');
  });

  final xml = File('android/app/src/main/res/xml/file_paths.xml');
  if (Directory('android/app/src/main/res').existsSync() && !xml.existsSync()) {
    xml.createSync(recursive: true);
    xml.writeAsStringSync('''<?xml version="1.0" encoding="utf-8"?>
<paths>
    <root-path name="root" path="."/>
    <external-path name="external" path="."/>
    <cache-path name="cache" path="."/>
</paths>
''');
    stdout.writeln('wrote ${xml.path}');
  }

  patch('android/app/build.gradle.kts', (s) {
    s = s.replaceFirst(RegExp(r'minSdk = [^\n]+'), 'minSdk = 24');
    // Same key on every build (CI and PC) so a new APK installs over the old one.
    if (!s.contains('tool/debug.keystore')) {
      s = s.replaceFirst('android {',
          'android {\n    signingConfigs {\n        getByName("debug") {\n            storeFile = file("../../tool/debug.keystore")\n        }\n    }');
    }
    if (!s.contains('checkReleaseBuilds')) {
      s = s.replaceFirst('android {', 'android {\n    lint {\n        checkReleaseBuilds = false\n        abortOnError = false\n    }');
    }
    if (!s.contains('androidx.core:core')) {
      s = '$s\ndependencies {\n    implementation("androidx.core:core-ktx:1.13.1")\n    implementation("com.google.android.gms:play-services-auth:21.3.0")\n}\n';
    }
    return s;
  });

  // Some plugins still compile against an old Android API; Flutter needs 36+.
  patch('android/build.gradle.kts', (s) {
    if (s.contains('ncommander-compileSdk')) return s;
    return '''$s
// ncommander-compileSdk: raise old plugins to the API level Flutter requires.
subprojects {
    plugins.withId("com.android.library") {
        extensions.configure<com.android.build.api.variant.LibraryAndroidComponentsExtension> {
            finalizeDsl { ext ->
                if ((ext.compileSdk ?: 0) < 36) ext.compileSdk = 36
            }
        }
    }
}
''';
  });

  final kt = File('tool/android/MainActivity.kt');
  final ktDir = Directory('android/app/src/main/kotlin/ro/noraz/ncommander');
  if (kt.existsSync() && ktDir.existsSync()) {
    kt.copySync('${ktDir.path}/MainActivity.kt');
    stdout.writeln('copied MainActivity.kt');
  }
}
